const RoomGrid = ({ rooms }) => {
  if (!Array.isArray(rooms)) {
    console.error('RoomGrid received invalid rooms data:', rooms);
    return <p>Error: Room data is invalid.</p>;
  }

  return (
    <div className="room-grid">
      {rooms.map((room) => (
        <div
          key={room.number}
          className={`room ${room.booked ? 'booked' : ''}`}
          title={`Room ${room.number}`}
        >
          {room.number}
        </div>
      ))}
    </div>
  );
};

export default RoomGrid;
